/*
 * Плагин TinyMCE fm: «Изображение» в панели и меню «Вставка» открывает файловый менеджер админки
 * (window.fileManager.open, пакет growtask/simflex-file-manager). Картинка вставляется тегом img,
 * другой файл — ссылкой; в позицию курсора редактора, из которого открыт менеджер.
 */
tinymce.PluginManager.add('fm', function (editor) {
    const escape = (text) => editor.dom.encode(text);
    const openFileManager = () => {
        window.fileManager?.open({
            multiple: true,
            onSelect: (files) => {
                editor.focus();
                editor.insertContent(files.map((file) => (file.isImage
                    ? `<img src="${escape(file.url)}" alt="" />`
                    : `<a href="${escape(file.url)}">${escape(file.name)}</a>`)).join(''));
            },
        });
    };

    editor.ui.registry.addButton('fm', {
        onAction: openFileManager,
        tooltip: 'Файлы',
        icon: 'image',
    });

    editor.ui.registry.addMenuItem('fm', {
        onAction: openFileManager,
        text: 'Изображение или файл',
        icon: 'image',
    });

    return {
        getMetadata: () => ({
            name: 'FileManager',
            url: 'https://github.com/growtask/simflex-file-manager',
        }),
    };
});
